using GastricCancerDetection.Application.Interfaces; using GastricCancerDetection.Infrastructure.Persistence; using Microsoft.EntityFrameworkCore;
namespace GastricCancerDetection.Infrastructure.Services; public class AnalysisRunService:IAnalysisRunService { private readonly GastricCancerDbContext _db; public AnalysisRunService(GastricCancerDbContext db)=>_db=db; public async Task<object?> GetAsync(int runId,CancellationToken ct=default){var run=await _db.AnalysisRuns.AsNoTracking().FirstOrDefaultAsync(x=>x.RunId==runId,ct);if(run==null)return null;return new {run.RunId,run.StatusId,run.PipelineVersion,run.Dataset,run.GenomeBuild,run.PythonVersion,run.Parameters,run.StartTime,run.EndTime,run.ErrorMessage};} }
